//! Typed operations: the one way people, apps and AI models change a mesh. An [`Op`] is plain data (JSON on the
//! wire, tagged by `"op"`), so it can be logged, replayed, validated against `spec/ops.schema.json` and generated by a
//! model. Applying the same op to the same mesh gives the same result on every platform.
//!
//! Numbers arrive as f64 and are rounded to f32 once, at the kernel boundary, exactly as a JavaScript caller's would.

use crate::mesh::Mesh;
use crate::region::{area, rad, Area, BoxRegion};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Bumped on any change to an op's meaning or fields. Additive changes (a new op, a new optional field) bump the
/// minor version; anything else bumps the major.
pub const OPS_VERSION: &str = "0.4.0";

pub type Rgb = [u8; 3];

/// One edit.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(
    tag = "op",
    rename_all = "camelCase",
    rename_all_fields = "camelCase",
    deny_unknown_fields
)]
pub enum Op {
    /// Delete the faces whose centroid is inside the box, or with `invert` every face outside it. Vertices no face uses
    /// any more are dropped. Count: faces removed.
    RemoveBox {
        #[serde(rename = "box")]
        region: BoxRegion,
        #[serde(default)]
        invert: bool,
    },
    /// Cut the box out of the surface. Triangles crossing its boundary are split along it, so the hole has exactly
    /// the box's shape. Count: triangles cut or removed.
    CarveBox {
        #[serde(rename = "box")]
        region: BoxRegion,
    },
    /// Smooth the surface inside the box (everywhere without one). The default Taubin method removes noise without
    /// shrinking the shape; `laplacian` relaxes harder and does shrink. Count: vertices moved.
    Smooth {
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        #[serde(default = "one")]
        iterations: u32,
        /// 0..1, how far each pass moves a vertex toward the average of its neighbours.
        #[serde(default = "half")]
        strength: f64,
        #[serde(default)]
        method: SmoothMethod,
        /// Keep vertices on open edges (hole rims, outlines) where they are.
        #[serde(default = "yes")]
        keep_boundary: bool,
    },
    /// Merge vertices on a grid of `cell` meters: fast and uniform, but rounds off detail. Prefer `simplify`.
    /// Count: faces left.
    Decimate { cell: f64 },
    /// Reduce the face count by collapsing the edges whose removal changes the shape least (quadric error metric),
    /// keeping the surface manifold and its faces unflipped. Give `targetFaces` or `targetRatio` (0..1 of the current
    /// count; default 0.5). Count: faces left.
    Simplify {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        target_faces: Option<u32>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        target_ratio: Option<f64>,
        /// Keep open edges (hole rims, outlines) in shape.
        #[serde(default = "yes")]
        keep_boundary: bool,
    },
    /// A brush stroke: each dab moves or recolours the vertices within `radius` of its centre, with a smooth falloff.
    /// Dabs apply in order, so a stroke sent in pieces gives the same mesh as the whole stroke. Count: vertices
    /// touched.
    Sculpt {
        brush: crate::sculpt::Brush,
        dabs: Vec<crate::sculpt::Dab>,
        /// Meters.
        radius: f64,
        /// 0..1 per dab.
        #[serde(default = "half")]
        strength: f64,
        /// Lower instead of raise (draw, inflate) or spread instead of gather (pinch).
        #[serde(default)]
        invert: bool,
        /// The paint brush's colour.
        #[serde(default = "light_grey")]
        color: Rgb,
        /// Direction the brush points (camera toward surface). Normals are turned to face it, so `draw` raises the
        /// surface toward the person sculpting even where a scan's winding is unreliable.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        view: Option<[f64; 3]>,
    },
    /// Close holes (boundary loops of up to `maxEdges` edges). Each loop is triangulated in its best-fit plane by
    /// ear clipping, so concave holes close cleanly without new vertices. Count: faces added.
    FillHoles {
        #[serde(default = "sixty_four")]
        max_edges: u32,
    },
    /// Split edges longer than `maxEdge` meters (only inside the box when given) so flat faces can hold detail.
    /// Count: faces after.
    Subdivide {
        max_edge: f64,
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        #[serde(default = "six")]
        passes: u32,
        #[serde(default = "max_faces")]
        max_faces: u32,
    },
    /// Push vertices along their normals by fractal noise: chips, pitting, uneven stone. Count: vertices moved.
    Roughen {
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        /// Largest displacement, meters.
        amplitude: f64,
        /// Feature size, meters.
        scale: f64,
        #[serde(default = "four")]
        octaves: u32,
        #[serde(default = "one")]
        seed: u32,
        /// Meters over which the effect eases off toward the box boundary.
        #[serde(default)]
        edge: f64,
        /// Crack-like ridges instead of soft lumps.
        #[serde(default)]
        ridged: bool,
    },
    /// Vary vertex colours with noise. Count: vertices changed.
    Tint {
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        #[serde(default = "grey")]
        a: Rgb,
        #[serde(default = "grey")]
        b: Rgb,
        scale: f64,
        /// Stretches the noise per axis (a long x stretch gives wood grain).
        #[serde(default = "ones")]
        stretch: [f64; 3],
        #[serde(default = "three")]
        octaves: u32,
        #[serde(default = "one")]
        seed: u32,
        /// 0..1.
        strength: f64,
        #[serde(default)]
        mode: TintMode,
    },
    /// Bake ambient occlusion into the vertex colours. Run once. Count: vertices shaded.
    BakeShadows {
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        #[serde(default = "half")]
        strength: f64,
        #[serde(default = "two")]
        radius: f64,
        #[serde(default = "quarter")]
        cell: f64,
        #[serde(default = "twenty_four")]
        samples: u32,
    },
    /// Colour the vertices in the box from the nearest source vertex within `maxDist`: the document's reference mesh
    /// with `fromReference`, otherwise this mesh's vertices outside the box. Count: vertices recoloured.
    MatchColor {
        #[serde(rename = "box")]
        region: BoxRegion,
        #[serde(default = "one_f")]
        max_dist: f64,
        #[serde(default = "one_f")]
        strength: f64,
        #[serde(default)]
        from_reference: bool,
    },
    /// Copy the faces whose centre is in the box, moved by `offset`, turned about the box's vertical axis and
    /// optionally mirrored. Count: faces added.
    CloneBox {
        #[serde(rename = "box")]
        region: BoxRegion,
        offset: [f64; 3],
        #[serde(default)]
        rotate_deg: f64,
        #[serde(default)]
        mirror_x: bool,
        #[serde(default)]
        mirror_z: bool,
    },
    /// Paint the vertices inside the box. Count: vertices painted.
    Paint {
        #[serde(rename = "box")]
        region: BoxRegion,
        color: Rgb,
    },
    /// Add a solid box filling `box`. Count: faces added.
    AddBox {
        #[serde(rename = "box")]
        region: BoxRegion,
        #[serde(default = "light_grey")]
        color: Rgb,
    },
    /// Add a ramp (a wedge) filling `box`: it rises from the bottom of the box's -z face to the top of its +z face, in
    /// the box's own frame (so `yawDeg` turns the direction it climbs). Count: faces added.
    AddRamp {
        #[serde(rename = "box")]
        region: BoxRegion,
        #[serde(default = "light_grey")]
        color: Rgb,
    },
    /// Place a linked instance of another object (`"scan:<id>"`) in the document's scene: the object's bounding-box
    /// bottom centre goes to `position`, scaled by `scale` and turned about that point: `rollDeg` about +z, then
    /// `pitchDeg` about +x, then `yawDeg` about +y. The instance points at the object rather than copying it, so when
    /// the object changes every instance of it changes too. Acts on a document's scene, not on a bare mesh. Count: 1.
    PlaceObject {
        /// Names the instance within this document; later ops refer to it.
        id: String,
        object: String,
        position: [f64; 3],
        #[serde(default, skip_serializing_if = "is_zero")]
        yaw_deg: f64,
        /// Tilt about +x, degrees (applied before the yaw).
        #[serde(default, skip_serializing_if = "is_zero")]
        pitch_deg: f64,
        /// Tilt about +z, degrees (applied first).
        #[serde(default, skip_serializing_if = "is_zero")]
        roll_deg: f64,
        #[serde(default = "one_f")]
        scale: f64,
    },
    /// Move, turn or scale a placed instance (the new values replace the old). Count: 1.
    MoveObject {
        id: String,
        position: [f64; 3],
        #[serde(default, skip_serializing_if = "is_zero")]
        yaw_deg: f64,
        /// Tilt about +x, degrees (applied before the yaw).
        #[serde(default, skip_serializing_if = "is_zero")]
        pitch_deg: f64,
        /// Tilt about +z, degrees (applied first).
        #[serde(default, skip_serializing_if = "is_zero")]
        roll_deg: f64,
        #[serde(default = "one_f")]
        scale: f64,
    },
    /// Take a placed instance out of the scene. Count: 1.
    RemoveObject { id: String },
    /// Turn a placed instance into ordinary geometry of the document's own mesh, where it can be sculpted and painted.
    /// It no longer follows its object afterwards. Count: faces added.
    BakeObject { id: String },
    /// Add an upright cylinder, cone or taper standing on `base`. Count: faces added.
    AddFrustum {
        base: [f64; 3],
        radius_bottom: f64,
        radius_top: f64,
        height: f64,
        #[serde(default = "twenty_four")]
        segments: u32,
        #[serde(default = "light_grey")]
        color: Rgb,
    },
    /// Add an ellipsoid. Count: faces added.
    AddSphere {
        center: [f64; 3],
        radii: [f64; 3],
        #[serde(default = "twenty_four")]
        segments: u32,
        #[serde(default = "twelve")]
        rings: u32,
        #[serde(default = "light_grey")]
        color: Rgb,
    },
    /// Revolve a profile of [radius, height] pairs (2 to 256) about the vertical axis through `base`: columns, vases,
    /// domes. Count: faces added.
    AddLathe {
        base: [f64; 3],
        profile: Vec<[f64; 2]>,
        #[serde(default = "thirty_two")]
        segments: u32,
        #[serde(default = "light_grey")]
        color: Rgb,
        #[serde(default = "yes")]
        capped: bool,
    },
    /// Extrude a floor plan of [x, z] points (3 to 512) straight up from `y0` by `height`. Count: faces added.
    AddExtrude {
        polygon: Vec<[f64; 2]>,
        y0: f64,
        height: f64,
        #[serde(default = "light_grey")]
        color: Rgb,
    },
    /// Stamp a stroke of Gaussian splats onto the surface: paint that lives in object space, independent of mesh
    /// resolution. Each dab sprays a jittered grid of stamps within `radius`; with `align` every stamp is raycast
    /// onto the surface along `view`, so paint wraps over bumps. A stamp landing on an earlier splat pours its
    /// opacity into it (`flow` per pass), so going over a spot builds coverage like a real spray can instead of
    /// stacking invisible layers. Count: stamps deposited.
    SplatPaint {
        dabs: Vec<crate::sculpt::Dab>,
        /// Brush footprint radius, meters.
        radius: f64,
        /// Splat radius (Gaussian sigma), meters.
        size: f64,
        /// Distance between stamp centres; defaults to `size`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        spacing: Option<f64>,
        #[serde(default = "light_grey")]
        color: Rgb,
        /// 0..1: opacity of a full-coverage stamp.
        #[serde(default = "one_f")]
        opacity: f64,
        /// 0..1: how much of `opacity` one pass deposits; the rest builds up on later passes.
        #[serde(default = "half")]
        flow: f64,
        /// 0..1: per-stamp size and opacity jitter, so dense strokes look organic rather than gridded.
        #[serde(default)]
        variation: f64,
        /// 0..1: noise-driven lightening and darkening per stamp (weathering, mottling).
        #[serde(default)]
        color_noise: f64,
        /// 0..1: how far fresh paint runs downward along the surface, like wet paint.
        #[serde(default)]
        drip: f64,
        #[serde(default)]
        seed: u32,
        /// Spray direction (camera toward surface). Default: straight down.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        view: Option<[f64; 3]>,
        /// Snap stamps onto the surface. With false they stay in the dab's tangent plane.
        #[serde(default = "yes")]
        align: bool,
    },
    /// Remove the splats within `radius` of any dab (pressure scales the radius): the eraser end of the brush.
    /// Count: splats removed.
    SplatErase {
        dabs: Vec<crate::sculpt::Dab>,
        /// Meters.
        radius: f64,
    },
    /// Blend the splats inside the box (everywhere without one) toward `color`. Count: splats recoloured.
    SplatTint {
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        color: Rgb,
        /// 0..1.
        #[serde(default = "half")]
        strength: f64,
    },
    /// Pour the splats into the vertex colours: each vertex near a splat is blended toward it, weighted by the
    /// splat's Gaussian and opacity. The bridge back to vertex colours for tools that only read those. With
    /// `clear` the splats are removed afterwards. Count: vertices recoloured.
    SplatBake {
        /// How far a splat reaches, meters. 0 (the default) means twice the mean splat radius, which covers
        /// seamlessly at any brush size.
        #[serde(default, skip_serializing_if = "is_zero")]
        radius: f64,
        /// 0..1.
        #[serde(default = "one_f")]
        strength: f64,
        #[serde(default)]
        clear: bool,
    },
    /// Move, turn and scale the mesh (or just the part inside `box`) about a pivot — the box's centre, or the world
    /// origin without one. Rotation applies roll (about +z), then pitch (about +x), then yaw (about +y). Splats in
    /// the region move, turn and scale with the surface. Count: vertices moved.
    Transform {
        #[serde(rename = "box", default, skip_serializing_if = "Option::is_none")]
        region: Option<BoxRegion>,
        #[serde(default, skip_serializing_if = "is_zero3")]
        translate: [f64; 3],
        #[serde(default, skip_serializing_if = "is_zero")]
        yaw_deg: f64,
        #[serde(default, skip_serializing_if = "is_zero")]
        pitch_deg: f64,
        #[serde(default, skip_serializing_if = "is_zero")]
        roll_deg: f64,
        #[serde(default = "one_f", skip_serializing_if = "is_one")]
        scale: f64,
    },
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum SmoothMethod {
    /// Alternating shrink and inflate steps (Taubin λ|μ): smooths without losing volume.
    #[default]
    Taubin,
    /// Plain averaging with the neighbours: stronger, and shrinks the shape.
    Laplacian,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum TintMode {
    /// Blend from colour `a` to `b` across the noise, mixed into what is there.
    #[default]
    Mix,
    /// Only lighten and darken what is there (weathering, stains).
    Shade,
}

fn is_zero(v: &f64) -> bool {
    *v == 0.0
}
fn is_zero3(v: &[f64; 3]) -> bool {
    *v == [0.0; 3]
}
fn is_one(v: &f64) -> bool {
    *v == 1.0
}
fn one() -> u32 {
    1
}
fn three() -> u32 {
    3
}
fn four() -> u32 {
    4
}
fn six() -> u32 {
    6
}
fn twelve() -> u32 {
    12
}
fn twenty_four() -> u32 {
    24
}
fn thirty_two() -> u32 {
    32
}
fn sixty_four() -> u32 {
    64
}
fn max_faces() -> u32 {
    900_000
}
fn half() -> f64 {
    0.5
}
fn quarter() -> f64 {
    0.25
}
fn one_f() -> f64 {
    1.0
}
fn two() -> f64 {
    2.0
}
fn ones() -> [f64; 3] {
    [1.0; 3]
}
fn grey() -> Rgb {
    [128; 3]
}
fn light_grey() -> Rgb {
    [180; 3]
}
fn yes() -> bool {
    true
}

/// What an op did. `count`'s meaning is given per op.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct OpOutcome {
    pub count: u64,
    pub vertices: u64,
    pub faces: u64,
}

/// The size of a mesh, as [`Mesh::measure`] reports it: volume (exact for a closed surface, 0 otherwise), surface
/// area, the area-weighted centroid, whether the surface is closed, and how many splats it carries.
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct Measure {
    /// Cubic meters, meaningful when `closed`.
    pub volume: f64,
    /// Square meters.
    pub surface_area: f64,
    /// Where the surface area balances, meters.
    pub centroid: [f64; 3],
    /// No boundary edges: the surface is watertight and `volume` is exact.
    pub closed: bool,
    /// Paint splats on the surface.
    pub splats: u64,
}

#[derive(Debug, thiserror::Error, PartialEq)]
pub enum OpError {
    #[error("{0}")]
    Invalid(String),
    #[error("matchColor with fromReference needs a reference mesh")]
    NoReference,
    #[error("no placed object has the id {0}")]
    NoInstance(String),
    #[error("an object with the id {0} is already placed")]
    DuplicateInstance(String),
    #[error("object {0} is not loaded in this document: set it before baking it")]
    MissingObject(String),
}

/// What an op may read besides the mesh it edits.
#[derive(Default, Clone, Copy)]
pub struct Context<'a> {
    pub reference: Option<&'a Mesh>,
    /// Connectivity of the mesh being edited, reused by `sculpt` between the pieces of a stroke. Must match the
    /// mesh's current faces.
    pub topology: Option<&'a crate::sculpt::SculptTopology>,
}

fn f3(v: [f64; 3]) -> [f32; 3] {
    [v[0] as f32, v[1] as f32, v[2] as f32]
}

fn finite(name: &str, v: f64) -> Result<f32, OpError> {
    if v.is_finite() {
        Ok(v as f32)
    } else {
        Err(OpError::Invalid(format!("{name} must be a finite number")))
    }
}

fn check_id(id: &str) -> Result<(), OpError> {
    if id.is_empty() || id.len() > 128 {
        return Err(OpError::Invalid("id must be 1 to 128 characters".into()));
    }
    Ok(())
}

fn check_transform(position: &[f64; 3], angles: [f64; 3], scale: f64) -> Result<(), OpError> {
    position
        .iter()
        .try_for_each(|&v| finite("position", v).map(|_| ()))?;
    finite("yawDeg", angles[0])?;
    finite("pitchDeg", angles[1])?;
    finite("rollDeg", angles[2])?;
    if finite("scale", scale)? <= 0.0 {
        return Err(OpError::Invalid("scale must be positive".into()));
    }
    Ok(())
}

fn check_box(b: &BoxRegion) -> Result<(), OpError> {
    if b.center
        .iter()
        .chain(&b.size)
        .chain([&b.yaw_deg])
        .any(|v| !v.is_finite())
    {
        return Err(OpError::Invalid("box values must be finite numbers".into()));
    }
    if b.size.iter().any(|&s| s < 0.0) {
        return Err(OpError::Invalid("box size must not be negative".into()));
    }
    Ok(())
}

impl Op {
    /// The op's name as it appears in JSON (`"carveBox"`).
    pub fn name(&self) -> &'static str {
        match self {
            Op::RemoveBox { .. } => "removeBox",
            Op::CarveBox { .. } => "carveBox",
            Op::Smooth { .. } => "smooth",
            Op::Decimate { .. } => "decimate",
            Op::Simplify { .. } => "simplify",
            Op::Sculpt { .. } => "sculpt",
            Op::FillHoles { .. } => "fillHoles",
            Op::Subdivide { .. } => "subdivide",
            Op::Roughen { .. } => "roughen",
            Op::Tint { .. } => "tint",
            Op::BakeShadows { .. } => "bakeShadows",
            Op::MatchColor { .. } => "matchColor",
            Op::CloneBox { .. } => "cloneBox",
            Op::Paint { .. } => "paint",
            Op::AddBox { .. } => "addBox",
            Op::AddRamp { .. } => "addRamp",
            Op::PlaceObject { .. } => "placeObject",
            Op::MoveObject { .. } => "moveObject",
            Op::RemoveObject { .. } => "removeObject",
            Op::BakeObject { .. } => "bakeObject",
            Op::AddFrustum { .. } => "addFrustum",
            Op::AddSphere { .. } => "addSphere",
            Op::AddLathe { .. } => "addLathe",
            Op::AddExtrude { .. } => "addExtrude",
            Op::SplatPaint { .. } => "splatPaint",
            Op::SplatErase { .. } => "splatErase",
            Op::SplatTint { .. } => "splatTint",
            Op::SplatBake { .. } => "splatBake",
            Op::Transform { .. } => "transform",
        }
    }

    /// Checks the op's values without touching a mesh.
    pub fn validate(&self) -> Result<(), OpError> {
        let opt = |b: &Option<BoxRegion>| b.as_ref().map_or(Ok(()), check_box);
        match self {
            Op::RemoveBox { region, .. }
            | Op::CarveBox { region }
            | Op::Paint { region, .. }
            | Op::AddBox { region, .. }
            | Op::AddRamp { region, .. } => check_box(region),
            Op::MatchColor {
                region,
                max_dist,
                strength,
                ..
            } => {
                check_box(region)?;
                finite("maxDist", *max_dist)?;
                finite("strength", *strength).map(|_| ())
            }
            Op::CloneBox {
                region,
                offset,
                rotate_deg,
                ..
            } => {
                check_box(region)?;
                offset
                    .iter()
                    .try_for_each(|&v| finite("offset", v).map(|_| ()))?;
                finite("rotateDeg", *rotate_deg).map(|_| ())
            }
            Op::Smooth {
                region, strength, ..
            } => {
                opt(region)?;
                finite("strength", *strength).map(|_| ())
            }
            Op::Decimate { cell } => finite("cell", *cell).map(|_| ()),
            Op::Simplify { target_ratio, .. } => match target_ratio {
                Some(r) if !(r.is_finite() && (0.0..=1.0).contains(r)) => Err(OpError::Invalid(
                    "targetRatio must be between 0 and 1".into(),
                )),
                _ => Ok(()),
            },
            Op::Sculpt {
                dabs,
                radius,
                strength,
                ..
            } => {
                if finite("radius", *radius)? <= 0.0 {
                    return Err(OpError::Invalid("radius must be positive".into()));
                }
                finite("strength", *strength)?;
                dabs.iter().try_for_each(|d| {
                    d.center
                        .iter()
                        .try_for_each(|&v| finite("dab center", v).map(|_| ()))?;
                    finite("pressure", d.pressure).map(|_| ())
                })
            }
            Op::FillHoles { .. } => Ok(()),
            Op::Subdivide {
                region, max_edge, ..
            } => {
                opt(region)?;
                finite("maxEdge", *max_edge).map(|_| ())
            }
            Op::Roughen {
                region,
                amplitude,
                scale,
                edge,
                ..
            } => {
                opt(region)?;
                finite("amplitude", *amplitude)?;
                finite("scale", *scale)?;
                finite("edge", *edge).map(|_| ())
            }
            Op::Tint {
                region,
                scale,
                stretch,
                strength,
                ..
            } => {
                opt(region)?;
                finite("scale", *scale)?;
                stretch
                    .iter()
                    .try_for_each(|&v| finite("stretch", v).map(|_| ()))?;
                finite("strength", *strength).map(|_| ())
            }
            Op::BakeShadows {
                region,
                strength,
                radius,
                cell,
                ..
            } => {
                opt(region)?;
                finite("strength", *strength)?;
                finite("radius", *radius)?;
                finite("cell", *cell).map(|_| ())
            }
            Op::PlaceObject {
                id,
                object,
                position,
                yaw_deg,
                pitch_deg,
                roll_deg,
                scale,
            } => {
                check_id(id)?;
                if object.is_empty() || object.len() > 256 {
                    return Err(OpError::Invalid(
                        "object must name an object, such as \"scan:<id>\"".into(),
                    ));
                }
                check_transform(position, [*yaw_deg, *pitch_deg, *roll_deg], *scale)
            }
            Op::MoveObject {
                id,
                position,
                yaw_deg,
                pitch_deg,
                roll_deg,
                scale,
            } => {
                check_id(id)?;
                check_transform(position, [*yaw_deg, *pitch_deg, *roll_deg], *scale)
            }
            Op::RemoveObject { id } | Op::BakeObject { id } => check_id(id),
            Op::AddFrustum {
                base,
                radius_bottom,
                radius_top,
                height,
                ..
            } => {
                base.iter()
                    .try_for_each(|&v| finite("base", v).map(|_| ()))?;
                finite("radiusBottom", *radius_bottom)?;
                finite("radiusTop", *radius_top)?;
                finite("height", *height).map(|_| ())
            }
            Op::AddSphere { center, radii, .. } => center
                .iter()
                .chain(radii)
                .try_for_each(|&v| finite("sphere", v).map(|_| ())),
            Op::AddLathe { base, profile, .. } => {
                if profile.len() < 2 || profile.len() > 256 {
                    return Err(OpError::Invalid(
                        "a lathe profile needs 2 to 256 points".into(),
                    ));
                }
                base.iter()
                    .chain(profile.iter().flatten())
                    .try_for_each(|&v| finite("lathe", v).map(|_| ()))
            }
            Op::AddExtrude {
                polygon,
                y0,
                height,
                ..
            } => {
                if polygon.len() < 3 || polygon.len() > 512 {
                    return Err(OpError::Invalid(
                        "an extrusion needs 3 to 512 points".into(),
                    ));
                }
                finite("y0", *y0)?;
                finite("height", *height)?;
                polygon
                    .iter()
                    .flatten()
                    .try_for_each(|&v| finite("polygon", v).map(|_| ()))
            }
            Op::SplatPaint {
                dabs,
                radius,
                size,
                spacing,
                opacity,
                flow,
                variation,
                color_noise,
                drip,
                view,
                ..
            } => {
                if finite("radius", *radius)? <= 0.0 {
                    return Err(OpError::Invalid("radius must be positive".into()));
                }
                if finite("size", *size)? <= 0.0 {
                    return Err(OpError::Invalid("size must be positive".into()));
                }
                if let Some(s) = spacing {
                    if finite("spacing", *s)? <= 0.0 {
                        return Err(OpError::Invalid("spacing must be positive".into()));
                    }
                }
                finite("opacity", *opacity)?;
                finite("flow", *flow)?;
                finite("variation", *variation)?;
                finite("colorNoise", *color_noise)?;
                finite("drip", *drip)?;
                if let Some(v) = view {
                    v.iter().try_for_each(|&x| finite("view", x).map(|_| ()))?;
                }
                dabs.iter().try_for_each(|d| {
                    d.center
                        .iter()
                        .try_for_each(|&v| finite("dab center", v).map(|_| ()))?;
                    finite("pressure", d.pressure).map(|_| ())
                })
            }
            Op::SplatErase { dabs, radius } => {
                if finite("radius", *radius)? <= 0.0 {
                    return Err(OpError::Invalid("radius must be positive".into()));
                }
                dabs.iter().try_for_each(|d| {
                    d.center
                        .iter()
                        .try_for_each(|&v| finite("dab center", v).map(|_| ()))?;
                    finite("pressure", d.pressure).map(|_| ())
                })
            }
            Op::SplatTint {
                region, strength, ..
            } => {
                opt(region)?;
                finite("strength", *strength).map(|_| ())
            }
            Op::SplatBake {
                radius, strength, ..
            } => {
                if finite("radius", *radius)? < 0.0 {
                    return Err(OpError::Invalid("radius must not be negative".into()));
                }
                finite("strength", *strength).map(|_| ())
            }
            Op::Transform {
                region,
                translate,
                yaw_deg,
                pitch_deg,
                roll_deg,
                scale,
            } => {
                opt(region)?;
                translate
                    .iter()
                    .try_for_each(|&v| finite("translate", v).map(|_| ()))?;
                finite("yawDeg", *yaw_deg)?;
                finite("pitchDeg", *pitch_deg)?;
                finite("rollDeg", *roll_deg)?;
                if finite("scale", *scale)? <= 0.0 {
                    return Err(OpError::Invalid("scale must be positive".into()));
                }
                Ok(())
            }
        }
    }

    /// Whether the op acts on a document's scene of placed objects rather than on its mesh alone.
    pub fn is_scene_op(&self) -> bool {
        matches!(
            self,
            Op::PlaceObject { .. }
                | Op::MoveObject { .. }
                | Op::RemoveObject { .. }
                | Op::BakeObject { .. }
        )
    }

    /// Whether the op can add, remove or rewire faces (as opposed to only moving vertices, changing colours or
    /// editing splats). Caches keyed on connectivity (a BVH, sculpt topology) survive the ops for which this is false.
    pub fn changes_topology(&self) -> bool {
        !matches!(
            self,
            Op::Smooth { .. }
                | Op::Sculpt { .. }
                | Op::Roughen { .. }
                | Op::Tint { .. }
                | Op::BakeShadows { .. }
                | Op::MatchColor { .. }
                | Op::Paint { .. }
                | Op::PlaceObject { .. }
                | Op::MoveObject { .. }
                | Op::RemoveObject { .. }
                | Op::SplatPaint { .. }
                | Op::SplatErase { .. }
                | Op::SplatTint { .. }
                | Op::SplatBake { .. }
                | Op::Transform { .. }
        )
    }

    /// Applies the op to `mesh`. Nothing changes when it fails validation.
    pub fn apply(&self, mesh: &mut Mesh, cx: Context) -> Result<OpOutcome, OpError> {
        self.validate()?;
        let f0 = mesh.face_count();
        let count = match self {
            Op::RemoveBox { region, invert } => mesh.remove_box(Area::from(region), *invert),
            Op::CarveBox { region } => mesh.carve_box(Area::from(region)),
            Op::Smooth {
                region,
                iterations,
                strength,
                method,
                keep_boundary,
            } => mesh.smooth(
                area(region.as_ref()),
                *iterations,
                *strength as f32,
                *method == SmoothMethod::Taubin,
                *keep_boundary,
            ),
            Op::Decimate { cell } => mesh.decimate(*cell as f32),
            Op::Simplify {
                target_faces,
                target_ratio,
                keep_boundary,
            } => {
                let target = match (target_faces, target_ratio) {
                    (Some(n), _) => *n as usize,
                    (None, r) => (f0 as f64 * r.unwrap_or(0.5)).round() as usize,
                };
                mesh.simplify(target, *keep_boundary)
            }
            Op::Sculpt {
                brush,
                dabs,
                radius,
                strength,
                invert,
                color,
                view,
            } => {
                let d: Vec<([f32; 3], f32)> = dabs
                    .iter()
                    .map(|d| (f3(d.center), d.pressure as f32))
                    .collect();
                mesh.sculpt(
                    *brush,
                    &d,
                    *radius as f32,
                    *strength as f32,
                    *invert,
                    *color,
                    view.map(f3),
                    cx.topology,
                )
            }
            Op::FillHoles { max_edges } => mesh.fill_holes(*max_edges),
            Op::Subdivide {
                max_edge,
                region,
                passes,
                max_faces,
            } => mesh.subdivide(*max_edge as f32, *passes, *max_faces, area(region.as_ref())),
            Op::Roughen {
                region,
                amplitude,
                scale,
                octaves,
                seed,
                edge,
                ridged,
            } => mesh.roughen(
                area(region.as_ref()),
                *amplitude as f32,
                *scale as f32,
                *octaves,
                *seed,
                *edge as f32,
                *ridged,
            ),
            Op::Tint {
                region,
                a,
                b,
                scale,
                stretch,
                octaves,
                seed,
                strength,
                mode,
            } => mesh.tint(
                area(region.as_ref()),
                *a,
                *b,
                *scale as f32,
                f3(*stretch),
                *octaves,
                *seed,
                *strength as f32,
                *mode == TintMode::Shade,
            ),
            Op::BakeShadows {
                region,
                strength,
                radius,
                cell,
                samples,
            } => mesh.bake_shadows(
                area(region.as_ref()),
                *strength as f32,
                *radius as f32,
                *cell as f32,
                *samples,
            ),
            Op::MatchColor {
                region,
                max_dist,
                strength,
                from_reference,
            } => {
                let reference = if *from_reference {
                    Some(cx.reference.ok_or(OpError::NoReference)?)
                } else {
                    None
                };
                mesh.match_color(
                    Area::from(region),
                    *max_dist as f32,
                    *strength as f32,
                    reference,
                )
            }
            Op::CloneBox {
                region,
                offset,
                rotate_deg,
                mirror_x,
                mirror_z,
            } => mesh.clone_box(
                Area::from(region),
                f3(*offset),
                rad(*rotate_deg),
                *mirror_x,
                *mirror_z,
            ),
            Op::Paint { region, color } => mesh.paint_box(Area::from(region), *color),
            Op::AddBox { region, color } => {
                let base = [
                    region.center[0] as f32,
                    (region.center[1] - region.size[1] / 2.0) as f32,
                    region.center[2] as f32,
                ];
                let s = f3(region.size);
                mesh.add_box(base, s[0], s[1], s[2], rad(region.yaw_deg), *color);
                mesh.face_count() - f0
            }
            Op::AddRamp { region, color } => {
                let base = [
                    region.center[0] as f32,
                    (region.center[1] - region.size[1] / 2.0) as f32,
                    region.center[2] as f32,
                ];
                let s = f3(region.size);
                mesh.add_ramp(base, s[0], s[1], s[2], rad(region.yaw_deg), *color);
                mesh.face_count() - f0
            }
            Op::PlaceObject { .. }
            | Op::MoveObject { .. }
            | Op::RemoveObject { .. }
            | Op::BakeObject { .. } => {
                return Err(OpError::Invalid(format!(
                    "{} acts on a document's scene, not on a bare mesh",
                    self.name()
                )))
            }
            Op::AddFrustum {
                base,
                radius_bottom,
                radius_top,
                height,
                segments,
                color,
            } => {
                mesh.add_frustum(
                    f3(*base),
                    *radius_bottom as f32,
                    *radius_top as f32,
                    *height as f32,
                    *segments,
                    *color,
                );
                mesh.face_count() - f0
            }
            Op::AddSphere {
                center,
                radii,
                segments,
                rings,
                color,
            } => {
                mesh.add_sphere(f3(*center), f3(*radii), *segments, *rings, *color);
                mesh.face_count() - f0
            }
            Op::AddLathe {
                base,
                profile,
                segments,
                color,
                capped,
            } => {
                let prof: Vec<[f32; 2]> =
                    profile.iter().map(|p| [p[0] as f32, p[1] as f32]).collect();
                mesh.add_lathe(&prof, *segments, f3(*base), *color, *capped);
                mesh.face_count() - f0
            }
            Op::AddExtrude {
                polygon,
                y0,
                height,
                color,
            } => {
                let pts: Vec<[f32; 2]> =
                    polygon.iter().map(|p| [p[0] as f32, p[1] as f32]).collect();
                mesh.add_extrude(&pts, *y0 as f32, *height as f32, *color);
                mesh.face_count() - f0
            }
            Op::SplatPaint {
                dabs,
                radius,
                size,
                spacing,
                color,
                opacity,
                flow,
                variation,
                color_noise,
                drip,
                seed,
                view,
                align,
            } => {
                let d: Vec<([f32; 3], f32)> = dabs
                    .iter()
                    .map(|d| (f3(d.center), d.pressure as f32))
                    .collect();
                mesh.splat_paint(
                    &d,
                    *radius as f32,
                    spacing.unwrap_or(*size) as f32,
                    *size as f32,
                    *color,
                    *opacity as f32,
                    *flow as f32,
                    *variation as f32,
                    *color_noise as f32,
                    *drip as f32,
                    *seed,
                    view.map(f3),
                    *align,
                )
            }
            Op::SplatErase { dabs, radius } => {
                let d: Vec<([f32; 3], f32)> = dabs
                    .iter()
                    .map(|d| (f3(d.center), d.pressure as f32))
                    .collect();
                mesh.splat_erase(&d, *radius as f32)
            }
            Op::SplatTint {
                region,
                color,
                strength,
            } => mesh.splat_tint(area(region.as_ref()), *color, *strength as f32),
            Op::SplatBake {
                radius,
                strength,
                clear,
            } => mesh.splat_bake(*radius as f32, *strength as f32, *clear),
            Op::Transform {
                region,
                translate,
                yaw_deg,
                pitch_deg,
                roll_deg,
                scale,
            } => {
                let a = area(region.as_ref());
                // The pivot: the box's centre, or the world origin when transforming everything.
                let pivot = region.map_or([0.0; 3], |b| f3(b.center));
                mesh.transform(
                    a,
                    f3(*translate),
                    rad(*roll_deg),
                    rad(*pitch_deg),
                    rad(*yaw_deg),
                    *scale as f32,
                    pivot,
                )
            }
        };
        Ok(OpOutcome {
            count: count as u64,
            vertices: mesh.vertex_count() as u64,
            faces: mesh.face_count() as u64,
        })
    }
}
